def lcs_length(s, t):
    from collections import Counter

    dp = Counter()
    max_len = 0

    for i in range(len(s)):
        for j in range(len(t)):
            if s[i] == t[j]:
                dp[i, j] = dp[i - 1, j - 1] + 1
                if dp[i, j] > max_len:
                    max_len = dp[i, j]

