def longest_common_subsequence(a, b):
    memo = {}

    def lcs(i, j):
        if i == len(a) or j == len(b):
            return ''
        if (i, j) in memo:
            return memo[(i, j)]

        if a[i] == b[j]:
            res = a[i] + lcs(i + 1, j + 1)
        else:
            res = max(
                lcs(i, j + 1),
                lcs(i + 1, j),
                key=len
            )
        memo[(i, j)] = res
        return res

    return lcs(0, 0)

